export const SUBJECT_FLASHCARDS_CSP_SCENARIO: SubjectFlashcard[] = [
  { id: "csp-scenario-001", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "a←[3,7,2,9]\nAPPEND(a,5)\nINSERT(a,2,6)\nREMOVE(a,4)\n列表下标从 1 开始，执行后 a 的内容是？\nA. 结果变为 [3,6,7,2,9,5]\nB. 结果变为 [3,6,7,2,5]\nC. 结果变为 [3,6,7,9,5]\nD. 结果变为 [3,6,7,2,9]", back: "答案：C\n简析：一句话解析：A 误把 REMOVE 当成按值删除（列表里没有 4，于是什么都没删），B 在插入后的列表里把数值 9 当成要删除的元素（混淆下标与元素值），D 误以为 REMOVE 删除的是最后一个元素。\n\n正确选项：结果变为 [3,6,7,9,5]", source: "ai-mcq", verified: true },
  { id: "csp-scenario-002", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "t←0\nFOR EACH x IN [2,5,3,80]\nIF (x MOD 2) = 0\nt←t+x\nELSE\nt←t-x\n执行后 t 的值是？\nA. t 等于 74\nB. t 等于 -74\nC. t 等于 82\nD. t 等于 90", back: "答案：A\n简析：一句话解析：B 把条件写反（偶数减、奇数加）得 -74，C 忽略了 ELSE 分支只累加偶数得 82，D 完全忽略条件把 4 个元素全部相加得 90。\n\n正确选项：t 等于 74", source: "ai-mcq", verified: true },
  { id: "csp-scenario-003", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某班 11 名学生每日屏幕使用时间（小时）排序后为 1、2、2、3、3、3、4、4、5、6、48，其中 48 是录入错误。若把 48 改成 4，下列哪项正确？\nA. 中位数与平均值都不变，因为数据个数没变\nB. 中位数与平均值都降低，其中中位数降得更多\nC. 中位数降低约 2，平均值降低约 4 小时\nD. 中位数保持不变，平均值降低约 4 小时", back: "答案：D\n简析：一句话解析：A 只看到数据个数没变就认为两个统计量都不变，B 误以为中位数比平均值更容易被极端值拉动，C 误以为中位数会变化（48 改成 4 后中位数仍是 3）。\n\n正确选项：中位数保持不变，平均值降低约 4 小时", source: "ai-mcq", verified: true },
  { id: "csp-scenario-004", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "某校想估计全校 1200 名学生的平均睡眠时长。调查者在上学日 7:30 只询问最早到校的 100 名学生，并且只通过校园 App 推送问卷。关于这个样本，哪项正确？\nA. 样本只有 100 人，把人数扩大到 300 人就能消除偏差\nB. 样本不具代表性，早到且装 App 的学生睡眠可能更少\nC. 这是在学生中随机抽样，因此结果可以推断因果关系\nD. 问卷通过校内 App 收集并加密传输，所以数据较为客观可靠", back: "答案：B\n简析：一句话解析：A 以为样本量能消除偏差，C 把方便样本误认成随机抽样并进一步推断因果，D 把传输加密误当成数据客观可靠。\n\n正确选项：样本不具代表性，早到且装 App 的学生睡眠可能更少", source: "ai-mcq", verified: true },
  { id: "csp-scenario-005", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "g←[58,72,91,45,88]\nt←0\nc←0\nFOR EACH x IN g\nIF x ≥ 60\nt←t+x\nc←c+1\nDISPLAY(t/c)\n程序输出约 83.7，这个输出表示？\nA. 全部 5 名学生分数的算术平均值\nB. 达到 60 分那 3 名学生的分数总和\nC. 达到 60 分那 3 名学生的平均分\nD. 达到 60 分学生总分占全班总分的比例", back: "答案：C\n简析：一句话解析：A 忽略了 IF 条件（全班平均约为 70.8），B 忘掉最后一次除法只看累加结果 251，D 把分子分母看成及格总分与全班总分（比值约 70.9%）。\n\n正确选项：达到 60 分那 3 名学生的平均分", source: "ai-mcq", verified: true },
  { id: "csp-scenario-006", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "某图像为 50×100 像素，每个像素的亮度用 4 位表示，未压缩存储。关于该图像，哪项正确？\nA. 需要 2500 字节，亮度共有 16 种取值\nB. 需要 20000 字节，亮度共有 16 种取值\nC. 需要 2500 字节，亮度共有 4 种取值\nD. 需要 5000 字节，亮度共有 256 种取值", back: "答案：A\n简析：一句话解析：B 把 4 位当成 4 字节算出 20000 字节，C 把位深直接当成取值个数（16 种误写成 4 种），D 忽略位深按每像素 1 字节计算并错用 8 位的色彩数。\n\n正确选项：需要 2500 字节，亮度共有 16 种取值", source: "ai-mcq", verified: true },
  { id: "csp-scenario-007", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "远程手术系统要求操作指令的往返延迟低于 50 毫秒，同时约需 20 Mbps 带宽传回视频。运营商把带宽从 20 Mbps 提升到 100 Mbps，两地之间的往返延迟没有变化。哪项正确？\nA. 带宽提高后延迟会随之降低，操作手感明显变好\nB. 带宽提高意味着不再发生丢包，两端传输必然可靠\nC. 延迟由两地距离决定，任何技术手段都无法降低它\nD. 视频回传画面可以更清晰，但操作手感不会改善", back: "答案：D\n简析：一句话解析：A 是「带宽大所以延迟低」的典型误解，B 把带宽与可靠性混为一谈（带宽不消除丢包），C 忽略了路由优化、边缘节点等确实能降低延迟的手段。\n\n正确选项：视频回传画面可以更清晰，但操作手感不会改善", source: "ai-mcq", verified: true },
  { id: "csp-scenario-008", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "一条消息被拆成 5 个包经分组交换网络发送，第 3 个包在途中丢失，接收方收到了其余 4 个包。哪项正确？\nA. 只要网络中存在冗余路径，任何包都不会丢失，因此接收方无需请求重传\nB. 丢失的包可以经另一条路径重传，接收方按序号重组成原消息\nC. 包必须按发送顺序沿同一条路径到达，否则整条消息必须作废\nD. 发送方必须把全部 5 个包重新发送一次，才能恢复整条消息", back: "答案：B\n简析：一句话解析：A 把冗余路径误当成永不丢包，C 误以为包必须走同一路径且严格有序到达，D 误以为丢一个包就要重发全部数据。\n\n正确选项：丢失的包可以经另一条路径重传，接收方按序号重组成原消息", source: "ai-mcq", verified: true },
  { id: "csp-scenario-009", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "学生在浏览器输入 school.example.edu 并成功打开页面。关于这次访问，哪项正确？\nA. 浏览器直接用域名与服务器通信，IP 地址只在解析失败时使用\nB. TCP/IP 负责把网页渲染成图像，HTTP 负责传输网页的比特\nC. 域名先被 DNS 解析成 IP 地址，浏览器再据此请求网页内容\nD. 一个域名只能对应一个 IP 地址，所以每次访问都连到同一台服务器", back: "答案：C\n简析：一句话解析：A 以为可以直接用域名通信，B 把 TCP/IP 与 HTTP 的职责对调还混入了渲染，D 误以为一个域名只能对应一个 IP（忽略了负载均衡与多台服务器）。\n\n正确选项：域名先被 DNS 解析成 IP 地址，浏览器再据此请求网页内容", source: "ai-mcq", verified: true },
  { id: "csp-scenario-010", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "学生要把 120 MB 的作业上传到服务器，上行带宽为 10 Mbps，忽略协议开销（1 字节 = 8 位）。上传大约需要多久？\nA. 大约 96 秒\nB. 大约 12 秒\nC. 大约 960 秒\nD. 大约 9600 秒", back: "答案：A\n简析：一句话解析：B 忽略字节与位的换算直接用 120÷10，C 换算后忘记除以带宽只留下 960，D 把除法写成乘法得到 960×10。\n\n正确选项：大约 96 秒", source: "ai-mcq", verified: true },
  { id: "csp-scenario-011", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "医院把病历同时存放在 3 个数据中心，其中 1 个因停电宕机时系统仍能访问数据，但每年的维护费用明显上升。哪项正确？\nA. 这体现了加密，因为数据分散存放后别人无法读取其中的内容\nB. 多份副本共享同一份数据，所以总存储与维护成本不会上升\nC. 这体现容错，而且只要有多份副本，数据就不会被错误修改\nD. 这体现容错，单个数据中心故障时仍可访问，只是成本上升", back: "答案：D\n简析：一句话解析：A 把冗余误当成加密，B 误以为副本不占额外存储与成本（副本反而增加总开销），C 错在以为冗余能保证数据内容正确。\n\n正确选项：这体现容错，单个数据中心故障时仍可访问，只是成本上升", source: "ai-mcq", verified: true },
  { id: "csp-scenario-012", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "某校园 App 收集以下数据：学号、出生日期、每天步数总计、电子邮箱、每天上课的教室编号。哪项正确？\nA. 只有姓名算个人可识别信息，学号和邮箱都只是普通编号\nB. 学号属于个人可识别信息，教室编号组合也可能定位到个人\nC. 只要不收集姓名，这些数据就不再属于个人信息，可对外公开\nD. 步数也属于个人可识别信息，因为它以数字形式存储", back: "答案：B\n简析：一句话解析：A 把 PII 等同于姓名，C 以为去掉姓名就等于去标识化，D 把数据格式（数字）当成敏感程度的判断依据。\n\n正确选项：学号属于个人可识别信息，教室编号组合也可能定位到个人", source: "ai-mcq", verified: true },
  { id: "csp-scenario-013", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某网站用 HTTPS 传输登录信息，服务器只保存「密码 + 随机盐」的哈希值，登录时比较哈希值。哪项正确？\nA. 哈希是一种可逆加密，服务器能用密钥把哈希还原成原密码\nB. HTTPS 能保证数据库里的密码不被攻击者读取，所以不必再做哈希\nC. 传输过程由 HTTPS 保护，数据库泄露后哈希也难以还原密码\nD. 加盐的作用是让同一密码每次都生成相同的哈希值，便于比较", back: "答案：C\n简析：一句话解析：A 把不可逆的哈希当成可逆加密，B 把传输加密的保护范围扩大到服务器数据库，D 把加盐误解成让哈希保持固定（加盐恰恰使每次结果不同）。\n\n正确选项：传输过程由 HTTPS 保护，数据库泄露后哈希也难以还原密码", source: "ai-mcq", verified: true },
  { id: "csp-scenario-014", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学生用「密码 + 手机验证码」登录校园系统，系统还按角色限制他只能查看自己的成绩。哪项正确？\nA. 密码与手机验证码用于认证，限制查看范围属于授权\nB. 验证码属于授权，因为它决定了你可以看到哪些页面\nC. 两者都属于加密措施，因为它们都保护了数据的机密性\nD. 有了双因素认证就能保证账号不被破解，因此不必再要求强密码", back: "答案：A\n简析：一句话解析：B 把认证手段误当成授权，C 把认证误当成加密（加密不判断身份），D 夸大双因素认证的作用并据此放弃强密码。\n\n正确选项：密码与手机验证码用于认证，限制查看范围属于授权", source: "ai-mcq", verified: true },
  { id: "csp-scenario-015", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 4, front: "某团队用过去 5 年的记录训练「预测学生是否需要补习」的模型。由于低收入学生过去较少获得补习，模型对这类学生的预测偏低。哪项正确？\nA. 只要把家庭收入这一字段删掉，模型的输出就不会再有偏差\nB. 偏差说明数据量不足，把记录增加到 10 倍即可消除\nC. 模型只是数学计算，因此不会产生任何实际社会影响\nD. 偏差来自历史数据的形成方式，删掉收入字段也无法消除", back: "答案：D\n简析：一句话解析：A 误以为去掉敏感字段就消除了偏差，B 把偏差当成样本量不足，C 忽略了算法结论对真实人群的影响。\n\n正确选项：偏差来自历史数据的形成方式，删掉收入字段也无法消除", source: "ai-mcq", verified: true },
  { id: "csp-scenario-016", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学校计划把学生出勤数据共享给一家公司，用于「旷课提醒」服务，公司会长期保留原始数据并用于改进自己的模型。哪项最需要关注？\nA. 数据共享的主要风险是传输变慢，可以与公司协商提高带宽\nB. 学生的数据被长期保留并二次使用，本人难以撤回或知情\nC. 学校与公司签了合同之后，学生就不再是利益相关者\nD. 出勤记录不属于个人信息，因此共享无需告知学生或征得同意", back: "答案：B\n简析：一句话解析：A 把隐私风险误当成带宽问题，C 以为签了合同学生就不再是利益相关者，D 误判出勤数据不属于个人信息而免去告知义务。\n\n正确选项：学生的数据被长期保留并二次使用，本人难以撤回或知情", source: "ai-mcq", verified: true },
  { id: "csp-scenario-017", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "学生对一个未排序的 1000 项列表直接使用二分查找来查找某个值。哪项正确？\nA. 二分查找对任何列表都有效，只要长度是 2 的幂\nB. 二分查找的比较次数与列表长度无关，总能在一步内找到\nC. 二分查找属于启发式方法，速度快但不能保证找到目标\nD. 二分查找要求列表已排序，否则查找结果可能不正确", back: "答案：D\n简析：一句话解析：A 用长度是否为 2 的幂代替了有序性这个前提，B 误以为比较次数与长度无关且能一步命中，C 把确定性的二分查找误当成启发式方法。\n\n正确选项：二分查找要求列表已排序，否则查找结果可能不正确", source: "ai-mcq", verified: true },
  { id: "csp-scenario-018", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某团队模拟食堂排队时间，假设每名学生点餐恰好用 30 秒，并且没有考虑课间高峰时学生同时到达。哪项正确？\nA. 模拟结果仅在假设成立时有效，忽略高峰则会使预测偏乐观\nB. 模拟使用了随机数，因此不需要验证，随机性会自动消除误差\nC. 只要增加模拟运行的次数，任何错误的假设都会被自动纠正\nD. 模拟是对真实系统的实验，其结论就是真实世界的因果结论", back: "答案：A\n简析：一句话解析：B 把随机性当成免检理由，C 以为多次运行能自动纠正假设错误，D 把模拟输出直接当成真实世界的因果结论。\n\n正确选项：模拟结果仅在假设成立时有效，忽略高峰则会使预测偏乐观", source: "ai-mcq", verified: true },
  { id: "csp-scenario-019", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 4, front: "关于「判断任意程序 P 在输入 I 上是否会停止」这个问题，哪项正确？\nA. 该问题不可判定，说明每个具体程序都无法判断自己是否会停止\nB. 该问题只是暂时没人写出算法，等算力提升后就能解决\nC. 该问题不存在通用算法，但许多具体程序的运行时间仍可分析\nD. 用启发式方法可以在有限步内对所有输入给出正确判断", back: "答案：C\n简析：一句话解析：A 把「通用算法不可判定」扩大成「每个具体程序都判断不了」，B 把不可判定误当成工程难题，D 把启发式方法误当成能保证正确判断的算法。\n\n正确选项：该问题不存在通用算法，但许多具体程序的运行时间仍可分析", source: "ai-mcq", verified: true },
  { id: "csp-scenario-020", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "快递公司要在 30 个城市之间找最短巡回路线，精确算法运行时间过长，公司改用「最近邻 + 局部调整」的方法。哪项正确？\nA. 只要运行足够久，这种方法最终一定能给出最优路线\nB. 这种方法能较快得到较好的路线，但不保证是最优解\nC. 精确算法太慢，说明最短巡回路线问题没有任何算法可解\nD. 最近邻属于精确算法，因此得到的结果一定是最优结果", back: "答案：B\n简析：一句话解析：A 误以为启发式方法只要多运行就能收敛到最优，C 把计算代价高误当成不可解，D 把最近邻这种贪心策略误当成精确算法。\n\n正确选项：这种方法能较快得到较好的路线，但不保证是最优解", source: "ai-mcq", verified: true },
  { id: "csp-scenario-021", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "学生做「校园失物招领」程序：用户提交物品描述与照片，程序在 300 条记录的列表中按关键字匹配并显示可能的联系方式。在 Create task 报告中写 program purpose 与 input 时，哪项最合适？\nA. 说明程序使用了列表与过程，因此目的是展示数据类型\nB. 只写「这个程序很有用，能帮助很多人」就足够，不必写输入\nC. 说明程序的目的是运行时不出错，输入为 CPU 与内存使用情况\nD. 说明目的是帮失物与失主匹配，输入是用户填写的描述与照片", back: "答案：D\n简析：一句话解析：A 把实现细节当成目的，B 只有泛泛的夸奖且缺少输入说明，C 把「不报错」当目的并写错了输入来源。\n\n正确选项：说明目的是帮失物与失主匹配，输入是用户填写的描述与照片", source: "ai-mcq", verified: true },
  { id: "csp-scenario-022", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "学生写了过程 FIND(items, key)，返回 key 第一次出现的下标，找不到时返回 -1，并在程序中多处调用。在 Create task 报告中描述该过程时，哪项最合适？\nA. 说明参数与返回值的含义，并说明它在程序中如何被调用\nB. 说明该过程属于抽象，因此报告中不必写出参数与返回值的含义\nC. 逐行说明过程内部每条语句的语法，以便读者照着抄写\nD. 说明该过程用了循环，因此属于数据抽象而不是过程抽象", back: "答案：A\n简析：一句话解析：B 把抽象误解为可以省略接口说明，C 把报告写成逐行语法讲解，D 混淆了过程抽象与数据抽象。\n\n正确选项：说明参数与返回值的含义，并说明它在程序中如何被调用", source: "ai-mcq", verified: true },
  { id: "csp-scenario-023", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学生的程序通过了案例 1、2、3 的测试，但输入空列表时会崩溃。按 Create task 对测试的要求，哪项最合适？\nA. 只要三个案例都通过，就能在报告中说明程序已经正确\nB. 记录每个案例的输入与预期结果，补充空列表情形并修改代码\nC. 崩溃说明这只是语法错误，应从报告中删掉该案例以免影响评分\nD. 只要把程序整体重写一遍，就不必记录之前用过的测试数据", back: "答案：B\n简析：一句话解析：A 把通过三个用例等同于程序正确，C 误判为空列表崩溃属于语法错误并想隐藏用例，D 以为重写代码后测试记录可以省略。\n\n正确选项：记录每个案例的输入与预期结果，补充空列表情形并修改代码", source: "ai-mcq", verified: true },
  { id: "csp-scenario-024", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学生的程序使用了网上下载的背景音乐、同学的一张照片，以及从公开网站抓取的 200 条用户评论。哪项最合适？\nA. 网上公开的内容都属于公有领域，因此可以直接使用且无需注明来源\nB. 只要在报告中写出音乐的名称，就不必考虑授权与个人数据\nC. 使用有许可的素材并注明来源，同时保护评论中的个人信息\nD. 抓取公开评论属于使用公开数据，因此不存在任何隐私问题", back: "答案：C\n简析：一句话解析：A 把公开可见误当成公有领域，B 只做署名却忽略授权与个人信息，D 误以为公开数据不存在隐私问题。\n\n正确选项：使用有许可的素材并注明来源，同时保护评论中的个人信息", source: "ai-mcq", verified: true },
  { id: "csp-scenario-025", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学生把「统计每名学生本周总步数」写成过程 TOTAL(steps, days)，并在主程序中多处调用。关于抽象与报告内容，哪项正确？\nA. 过程属于抽象，因此报告中不必说明程序面向的用户是谁\nB. 因为过程会被多次调用，所以它属于模拟而不是一种抽象方法\nC. 过程内部的变量名必须与调用处一致，否则参数传递会失效\nD. 带参数的过程属于抽象，报告中仍需说明面向的用户与用途", back: "答案：D\n简析：一句话解析：A 以为用了抽象就不必写用户说明，B 把过程抽象误当成模拟，C 编造了参数传递对变量名的要求。\n\n正确选项：带参数的过程属于抽象，报告中仍需说明面向的用户与用途", source: "ai-mcq", verified: true },
  { id: "csp-scenario-026", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某传感器输出的 8 位二进制读数为 0010 1101，工程师把该读数加 5 后仍用 8 位二进制保存。加 5 之后的 8 位表示是？\nA. 0010 1000，因为逐位相加时没有向高位进位\nB. 0010 1110，因为加 5 只把末两位改成 10\nC. 0011 0001，因为把原读数当作十进制的 44\nD. 0011 0010，因为原读数 45 加 5 得 50", back: "答案：D\n简析：一句话解析：A 逐位相加时忽略了进位（得 0010 1000 = 40），B 忽略向第 5 位的进位、只把末两位改成 10（得 0010 1110 = 46），C 把二进制读数误当成十进制 44 再加 5（得 0011 0001 = 49）；0010 1101 = 45，45+5 = 50 = 0011 0010。\n\n正确选项：0011 0010，因为原读数 45 加 5 得 50", source: "ai-mcq", verified: true },
  { id: "csp-scenario-027", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "一块 200×150 像素的位图，每个像素用 24 位（RGB 各 8 位）表示，且未压缩保存。该位图的数据部分约占多少字节？\nA. 90000 字节，即 720000 位再除以 8\nB. 30000 字节，即把每个像素按 1 个字节计算\nC. 720000 字节，即把每像素的 24 位当成 24 字节\nD. 15000 字节，即把每个像素按 4 位来计算", back: "答案：A\n简析：一句话解析：B 把每个像素按 1 字节算（得 30000 字节），C 把 24 位当成 24 字节（得 720000 字节），D 把位深误当成 4 位（得 15000 字节）；200×150 = 30000 像素，×24 = 720000 位，÷8 = 90000 字节。\n\n正确选项：90000 字节，即 720000 位再除以 8", source: "ai-mcq", verified: true },
  { id: "csp-scenario-028", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 4, front: "学生把 60 MB 的照片集导出分享：人眼不敏感的高频细节被丢弃，大片同色区域改用「只存一次 + 记录出现位置」的方式压小，压缩后为 10 MB；但照片的拍摄时间、设备型号与经纬度仍完整保留。哪项正确？\nA. 两步都是无损压缩，因为照片仍能正常打开\nB. 两步都是有损压缩，因为体积缩小到六分之一\nC. 去细节有损、同色区域压缩可逆，元数据仍保留\nD. 同色区域压缩丢弃了部分像素颜色值，是有损压缩", back: "答案：C\n简析：一句话解析：A 以为解压后能正常打开就说明无损（被丢弃的高频细节已不可还原），B 用 60÷10 = 6 的压缩比反推算法类型（压缩比与有无损失无关），D 把「只存一次 + 记录出现位置」的编码当成丢弃颜色值（该编码可完全还原）；丢弃高频细节属于有损压缩。\n\n正确选项：去细节有损、同色区域压缩可逆，元数据仍保留", source: "ai-mcq", verified: true },
  { id: "csp-scenario-029", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某社区 9 户家庭的月用电量为 180、190、200、210、220、230、240、250、980 度，其中 980 度是抄表错误。社区想描述「典型一户」的用电水平。哪项正确？\nA. 平均值 300 度更能代表典型水平，因为它用到了全部九个数据点\nB. 中位数 220 度更能代表典型水平，平均值被 980 度抬高\nC. 平均值与中位数都等于 300 度，都不受极端值影响\nD. 中位数等于 300 度，说明抄表错误没有影响任何统计量", back: "答案：B\n简析：一句话解析：A 认为用到全部数据就更可靠，忽略了平均值被 980 抬高到 300，C 误以为中位数也是 300（9 个数排序后第 5 个是 220），D 误以为抄表错误没有影响任何统计量；中位数 220 度比平均值 300 度更能代表典型水平。\n\n正确选项：中位数 220 度更能代表典型水平，平均值被 980 度抬高", source: "ai-mcq", verified: true },
  { id: "csp-scenario-030", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "某项目让公众用手机上报路边停车位是否被占用，一周内收到 50 万条上报；同一时刻同一车位常被多人重复上报，结论互相矛盾。哪项正确？\nA. 众包能快速获取数据，但需去重与交叉核对保证质量\nB. 数据量足够大，矛盾的上报可以互相抵消，无须处理\nC. 众包数据由志愿者自愿提供，所以比传感器数据更客观\nD. 只要上报人数继续增加，错误比例就会自动降到零", back: "答案：A\n简析：一句话解析：B 误以为数据量大就能让矛盾记录自动抵消（重复与冲突上报仍需去重和交叉核对），C 把志愿者自愿上报当成比传感器更客观（众包存在系统性偏差），D 误以为上报人数增加会让错误比例降到零。\n\n正确选项：众包能快速获取数据，但需去重与交叉核对保证质量", source: "ai-mcq", verified: true },
  { id: "csp-scenario-031", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "一份 500 行的跑步记录表：45 行的距离单位是英里（1 英里≈1.6 公里），其余是公里；12 行距离缺失；另有 30 行是同一次跑步被重复导入。要统计「平均每次跑步距离」，哪项做法最合适？\nA. 把缺失的 12 行填成 0，因为总行数不变\nB. 只删掉重复的 30 行，单位与缺失值留到分析阶段处理\nC. 直接按 500 行计算平均值，个别误差会被大样本摊薄\nD. 先把距离单位统一为公里，再处理缺失值并去掉重复记录", back: "答案：D\n简析：一句话解析：A 把缺失值填成 0 会把平均距离拉低，B 只去重仍留下混用的英里与公里（1 英里≈1.6 公里），C 直接按 500 行统计会把单位错误、缺失值和重复记录一起算进平均值；应先统一单位、处理缺失值、再去重。\n\n正确选项：先把距离单位统一为公里，再处理缺失值并去掉重复记录", source: "ai-mcq", verified: true },
  { id: "csp-scenario-032", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "某团队要分析一学期的食堂刷卡数据：①从学校系统导出原始刷卡记录 ②去掉重复记录并统一时间格式 ③统计每人每周用餐次数 ④用柱状图向校方汇报。按数据处理流程（收集、清理、分析、可视化与结论），哪项做法最合适？\nA. 数据来源可靠，所以导出记录后直接统计次数并绘图即可，无须清理\nB. 导出原始记录，再去重并统一格式，然后统计次数，最后绘图汇报\nC. 导出记录后先统计次数，再去重、统一格式并绘图汇报\nD. 导出记录后直接绘图汇报，去重与统一格式放到最后处理", back: "答案：B\n简析：一句话解析：A 误以为数据来源可靠就不必清理（重复记录与格式不一致依然存在），C 在清理之前先统计次数，把清理放到了分析后面，D 把清理放到可视化之后，等于用未清理的数据得出结论；收集→清理→分析→可视化与结论才是正确顺序。\n\n正确选项：导出原始记录，再去重并统一格式，然后统计次数，最后绘图汇报", source: "ai-mcq", verified: true },
  { id: "csp-scenario-033", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学校用柱状图比较两个班的平均分：一班 4.91 分、二班 5.00 分（满分 5 分），纵轴范围设为 4.90～5.00，图上二班的柱子看起来约是一班的十倍高。哪项正确？\nA. 平均值只相差 0.09 分也很大，图形没有夸大差异\nB. 纵轴从 4.90 开始只是排版上的选择，不会影响读者对差异的判断\nC. 纵轴截断放大了视觉差异，比较差异应看数值而非柱高\nD. 图上相差十倍说明两个班的平均分确实相差十倍", back: "答案：C\n简析：一句话解析：A 以为 4.91 与 5.00 相差 0.09 分也是很大的差距，忽略了图形被截断放大，B 截断纵轴会把 0.01 与 0.10 的柱高差放大成十倍，并不是无关紧要的排版选择，D 把柱高 10 倍的比例当成真实分差；柱高 0.01 与 0.10 的对比只是纵轴从 4.90 起造成的错觉。\n\n正确选项：纵轴截断放大了视觉差异，比较差异应看数值而非柱高", source: "ai-mcq", verified: true },
  { id: "csp-scenario-034", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "数据表明「每天看短视频超过 3 小时的学生，平均成绩比其他人低 12 分」。有人据此认为看短视频导致成绩下降。哪项是最合理的判断？\nA. 可能存在睡眠不足等第三因素同时影响这两个变量\nB. 看短视频导致成绩下降，所以二者是因果关系\nC. 成绩低的学生才去看短视频，所以二者不存在相关性\nD. 相关系数足够大就可判定因果方向，不必考虑其他变量", back: "答案：A\n简析：一句话解析：B 由相关性直接断定因果关系，C 用「成绩低才看短视频」的反向解释否定了数据中确实存在的相关性，D 误以为相关系数足够大就能确定因果方向；睡眠不足等第三因素可能同时影响看视频时长与成绩。\n\n正确选项：可能存在睡眠不足等第三因素同时影响这两个变量", source: "ai-mcq", verified: true },
  { id: "csp-scenario-035", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "学生模拟食堂排队：假设每名学生取餐耗时在 20～40 秒之间随机取值、每人只取一次餐，但忽略了下课时大量学生同时到达的情况。运行 1000 次后平均等待时间为 1.2 分钟。哪项正确？\nA. 随机数已经包含真实世界的全部变异，结果可直接使用\nB. 只要把运行次数提高到 100 万次，假设偏差就会消失\nC. 模拟属于对真实系统的实验，其输出必然是真实结论\nD. 假设与真实到达规律不符，模型很可能低估高峰等待时间", back: "答案：D\n简析：一句话解析：A 把随机数当成真实世界变异的全部来源，忽略了模型假设本身可能有偏，B 误以为把运行次数提高到 100 万次就能修正错误的到达假设，C 把模拟输出直接当成真实世界的因果结论；忽略下课高峰会使等待时间被低估。\n\n正确选项：假设与真实到达规律不符，模型很可能低估高峰等待时间", source: "ai-mcq", verified: true },
  { id: "csp-scenario-036", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "列表 a 已按升序排列且含 4096 项，程序用二分查找判断目标值是否在 a 中，每次比较后把搜索范围减半：\nlow←1\nhigh←4096\nREPEAT UNTIL (low > high)\nmid←(low+high)/2 的整数部分\n比较 a[mid] 与目标值并据此折半缩小范围\n要把搜索范围从 4096 项缩小到只剩 1 项，最多需要减半多少次？\nA. 4096 次，因为最坏情况要逐项检查列表每一项\nB. 12 次，因为 2 的 12 次方等于 4096\nC. 64 次，因为 4096 的平方根正好等于 64\nD. 2048 次，因为第一次比较后就能排除列表中的一半项", back: "答案：B\n简析：一句话解析：A 把二分查找当成逐项检查（那是线性查找的 4096 次），C 用平方根代替对数（4096 的平方根 64 与减半次数无关），D 把「第一轮排除一半」当成总次数；2 的 12 次方等于 4096，所以 12 次减半后范围只剩 1 项。\n\n正确选项：12 次，因为 2 的 12 次方等于 4096", source: "ai-mcq", verified: true },
  { id: "csp-scenario-037", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "某安全团队想做一个工具：对任意给定的程序与任意输入，判断它在运行时是否一定会访问网络并上传用户数据。这类针对任意程序的语义判断无法用算法完全实现，团队只好改用可疑行为评分。哪项正确？\nA. 只要换用速度更快的计算机，这个判断程序迟早能写出\nB. 无法实现说明判断程序里有语法错误，需要逐行修改\nC. 启发式方法能在有限步内对所有输入给出正确判断\nD. 该问题本身不可判定，启发式评分只能提供有用猜测", back: "答案：D\n简析：一句话解析：A 把不可判定当成算力不足的工程问题，B 把语义上不可判定误认为程序有语法错误，C 误以为启发式方法能在有限步内对所有输入保证正确；这类针对任意程序的判断不可判定，启发式评分只能给出可能有用的猜测。\n\n正确选项：该问题本身不可判定，启发式评分只能提供有用猜测", source: "ai-mcq", verified: true },
  { id: "csp-scenario-038", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某任务总耗时 100 秒，其中 80 秒可完美并行，20 秒必须串行执行。若用 8 台处理器并行执行可并行的部分，理论最短总耗时约为多少秒？\nA. 约 12.5 秒，因为 100 秒被平均分摊给 8 台处理器\nB. 约 20 秒，因为串行部分的 20 秒决定了最短总耗时\nC. 约 30 秒，即 20 秒串行加 80÷8 的 10 秒\nD. 约 10 秒，因为可并行的 80 秒只需除以 8", back: "答案：C\n简析：一句话解析：A 忽略了 20 秒串行部分，把 100 秒直接除以 8 得 12.5 秒，B 误以为总耗时等于串行部分的 20 秒，D 只算可并行部分 80÷8 = 10 秒而漏掉串行时间；20 + 80÷8 = 20 + 10 = 30 秒。\n\n正确选项：约 30 秒，即 20 秒串行加 80÷8 的 10 秒", source: "ai-mcq", verified: true },
  { id: "csp-scenario-039", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 4, front: "一年按 8760 小时计算，某服务单台服务器每年约宕机 87.6 小时（约 1% 的时间）。把服务部署到 3 台互为副本的服务器上后，只有 3 台同时宕机服务才中断；设各台宕机相互独立，则一年中服务中断时间的期望值约为？\nA. 约 32 秒，因为 0.01 的三次方乘 8760 小时\nB. 约 29 小时，因为把单机 87.6 小时平均分给 3 台\nC. 约 53 分钟，因为把 87.6 小时乘以 0.01\nD. 约 0 秒，因为只要有三份副本服务就绝不会中断", back: "答案：A\n简析：一句话解析：B 把单机 87.6 小时平均分给 3 台（得约 29 小时），忽略了中断要求三台同时宕机，C 只用一次 0.01 相乘（87.6×0.01 ≈ 53 分钟），少乘了两个因子，D 误以为有副本就绝不会中断；中断概率为 0.01³ = 10⁻⁶，8760×10⁻⁶ 小时 ≈ 0.526 分钟 ≈ 32 秒。\n\n正确选项：约 32 秒，因为 0.01 的三次方乘 8760 小时", source: "ai-mcq", verified: true },
  { id: "csp-scenario-040", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学生打开会议网站：浏览器先把域名解析成 IP 地址并通过 HTTP 请求页面，随后语音按 20 毫秒一帧用 UDP 发送；下载课件则使用 TCP，丢包后会自动重传。哪项正确？\nA. UDP 也会重传丢失的帧，所以两种协议可靠性相同\nB. 域名解析先于传输完成，UDP 不保证重传与顺序到达\nC. 域名解析由 HTTP 完成，IP 地址只用于给网页命名\nD. 使用 UDP 时应用无法感知丢帧，用户察觉不到卡顿", back: "答案：B\n简析：一句话解析：A 误以为 UDP 也会重传丢失的帧（重传由 TCP 或应用层负责），C 把域名解析归给 HTTP 并把 IP 地址当成网页名称，D 误以为应用无法感知丢帧、用户也不会察觉卡顿；域名先解析成 IP 再传输，UDP 不保证重传与顺序。\n\n正确选项：域名解析先于传输完成，UDP 不保证重传与顺序到达", source: "ai-mcq", verified: true },
  { id: "csp-scenario-041", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "把 3 GB 的文件上传到云盘（1 GB = 1000 MB，1 字节 = 8 位），链路带宽为 50 Mbps，实际吞吐只有带宽的 80%，往返延迟为 80 毫秒。忽略协议开销，上传约需要多长时间？\nA. 约 480 秒，因为 24000 兆位除以 50 Mbps\nB. 约 24000 秒，算出 24000 兆位后忘记除以带宽\nC. 约 60 秒，即把 3 GB 当成 3 Gbit 再除以 50\nD. 约 600 秒，因为 24000 兆位除以 40 Mbps", back: "答案：D\n简析：一句话解析：A 用 24000÷50 = 480 秒，忽略了实际吞吐只有带宽的 80%，B 算出 24000 兆位后忘记除以带宽，C 把 3 GB 当成 3 Gbit 直接除以 50（得 60 秒），漏掉字节转位的 8 倍；3000 MB×8 = 24000 兆位，24000÷40 = 600 秒，80 毫秒延迟可忽略。\n\n正确选项：约 600 秒，因为 24000 兆位除以 40 Mbps", source: "ai-mcq", verified: true },
  { id: "csp-scenario-042", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学生要把加密文件发给从未见面的老师：老师把公钥公布在网站上，学生用该公钥加密文件，老师用自己的私钥解密；学生还用老师的数字证书核对公钥确实属于老师。哪项正确？\nA. 公钥加密的内容由私钥解密，证书可确认公钥归属\nB. 公钥加密的密文只能用公钥解密，所以证书多余\nC. 数字证书的作用是压缩文件，使加密后的文件体积更小\nD. 对称加密也要先公布公钥，与公钥加密本质相同", back: "答案：A\n简析：一句话解析：B 误以为公钥加密的密文只能用公钥解密（实际由老师用私钥解密），因此把证书当成多余，C 把数字证书当成压缩工具，D 误以为对称加密也要先公布公钥；公钥加密配合证书验证身份，只有持有私钥的老师能解密。\n\n正确选项：公钥加密的内容由私钥解密，证书可确认公钥归属", source: "ai-mcq", verified: true },
  { id: "csp-scenario-043", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某校园系统登录时全程使用 HTTPS；密码在数据库中保存为「随机盐 + 哈希」；除密码外还要求输入手机验证码；登录后系统按身份只允许学生查看自己的成绩。哪项正确？\nA. HTTPS 保护了传输过程，因此数据库中的密码不必再加盐保存\nB. 手机验证码属于授权，因为它决定了你能进入哪些页面\nC. 传输加密、加盐哈希与验证码各保护不同环节，查看范围属授权\nD. 有了双因素认证，密码即使被钓鱼网站获取也不会造成损失", back: "答案：C\n简析：一句话解析：A 把传输加密的保护范围扩大到数据库中的静态数据，B 把手机验证码这种认证手段当成授权，D 夸大了双因素认证的作用（密码与验证码同时被钓鱼网站获取时仍会失守）；传输加密、加盐哈希与验证码各保护不同环节，查看范围由授权决定。\n\n正确选项：传输加密、加盐哈希与验证码各保护不同环节，查看范围属授权", source: "ai-mcq", verified: true },
  { id: "csp-scenario-044", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "学生收到一封邮件，声称来自学校 IT 部门，要求点击链接「验证邮箱密码」，否则 24 小时内停用账号；同一天，校园网站因大量来自各地的伪造请求而变得很慢。哪项正确？\nA. 邮件确实来自学校域名，说明这是真实通知，可以直接填写密码\nB. 该邮件是钓鱼式社会工程，网站变慢可能是 DDoS 攻击\nC. 网站变慢是因为有人用键盘记录程序窃取了管理员密码\nD. 只要电脑安装了杀毒软件，就可以在链接页面输入密码", back: "答案：B\n简析：一句话解析：A 仅凭邮件声称来自学校域名就判定通知真实，C 把网站变慢归因于键盘记录程序（大量伪造请求更符合 DDoS），D 误以为杀毒软件可以替代凭据保护；这类要求验证密码的紧迫邮件是典型的钓鱼式社会工程。\n\n正确选项：该邮件是钓鱼式社会工程，网站变慢可能是 DDoS 攻击", source: "ai-mcq", verified: true },
  { id: "csp-scenario-045", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "某医院公开一份数据集，删去了姓名和身份证号，只保留出生日期、邮政编码和就诊日期三个字段；研究者把它与公开的选民登记表对照，重新识别出部分患者的身份。哪项正确？\nA. 数据里已没有姓名，所以不可能重新识别出任何个人\nB. 只要再删除出生日期，这份数据集就绝不会被重新识别\nC. 字段组合就可能构成身份标识，去标识化仍可被重识别\nD. 出生日期与邮政编码只是普通编号，不属于个人可识别信息", back: "答案：C\n简析：一句话解析：A 以为删掉姓名就不可能重新识别出个人，B 误以为再删一个字段就能绝对防止重识别，D 把出生日期与邮政编码这类准标识符当成普通编号；多个字段组合与外部数据对照后即可重新识别，去标识化仍可能被重识别。\n\n正确选项：字段组合就可能构成身份标识，去标识化仍可被重识别", source: "ai-mcq", verified: true },
  { id: "csp-scenario-046", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "某公司用过去 8 年的录用记录训练简历筛选模型；由于历史上某个专业的录用比例偏高，模型给这个专业的简历打分更高。哪项正确？\nA. 模型只是数学计算，它的打分不会影响真实的人\nB. 只要把训练数据扩展到 30 年，偏差就会随数据量消失\nC. 模型在测试集上准确率高，就说明它不存在偏见\nD. 偏差来自历史录用数据本身，训练数据的选择影响公平性", back: "答案：D\n简析：一句话解析：A 忽略模型输出对真实人群的实际影响，B 误以为把训练数据从 8 年扩到 30 年就能让历史偏差消失，C 把测试集准确率高当成没有偏见；偏差来自历史录用数据本身的形成方式，训练数据的选择决定模型的公平性。\n\n正确选项：偏差来自历史录用数据本身，训练数据的选择影响公平性", source: "ai-mcq", verified: true },
  { id: "csp-scenario-047", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 2, front: "某地区 60% 的家庭没有宽带，学生只能用手机流量完成在线作业；学校给每名学生发了平板电脑，但作业平台要求上传 200 MB 的视频。哪项最需要关注？\nA. 平板电脑已经解决了问题，因为每名学生都拿到上网设备\nB. 手机流量的带宽与宽带相同，完成作业没有实际困难\nC. 接入差异不仅是设备问题，还包括带宽与费用的持续差距\nD. 只要学校长期提供免费流量，数字接入的差异就会永久消失", back: "答案：C\n简析：一句话解析：A 以为发了平板电脑就等于实现了接入平等，B 误以为手机流量与宽带的带宽相同、完成作业没有困难，D 误以为提供免费流量就能永久消除差异；家庭宽带覆盖率、带宽与持续费用都是数字接入差异的组成部分。\n\n正确选项：接入差异不仅是设备问题，还包括带宽与费用的持续差距", source: "ai-mcq", verified: true },
  { id: "csp-scenario-048", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "学生做「校园二手书交换」程序：用户输入书名与期望价格，程序在列表中查找匹配项并显示卖家联系方式。在 Create task 报告中说明 program purpose and function 时，哪项最合适？\nA. 目的写「程序用了列表，因此目的是演示数据类型」\nB. 说明目的是帮助同学交换二手书，功能是匹配并显示卖家\nC. 只写「这个程序很有用，能帮到很多同学」，不必描述功能\nD. 目的写「程序运行时不报错」，输入写 CPU 占用率", back: "答案：B\n简析：一句话解析：A 把实现细节（用了列表）当成程序的目的，C 只有泛泛的夸奖且没有说明程序功能，D 把「运行时不报错」当成目的并写错了输入来源；应说明程序目的是帮助同学交换二手书，功能是匹配并显示卖家联系方式。\n\n正确选项：说明目的是帮助同学交换二手书，功能是匹配并显示卖家", source: "ai-mcq", verified: true },
  { id: "csp-scenario-049", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 1, front: "学生把 300 条书籍记录存入列表 books，每条记录含书名、价格与卖家联系方式；又写了过程 SEARCH(books, key) 并在主程序中多次调用。在报告中说明抽象时，哪项最合适？\nA. books 是数据抽象、SEARCH 是过程抽象，都降低复杂度\nB. 列表只是数据容器，只有过程算抽象，所以只需说明 SEARCH\nC. 说明抽象时应逐行写出 SEARCH 内部的全部语句，便于读者实现\nD. 只有当 SEARCH 内部不再调用其它过程时，它才算过程抽象", back: "答案：A\n简析：一句话解析：B 误以为列表这种数据抽象不算抽象，只有过程才算，C 把报告写成逐行语法讲解（说明抽象应写接口与用途而非内部语句），D 过程抽象与它是否调用其它过程无关；books 属数据抽象、SEARCH 属过程抽象，两者都降低了程序复杂度。\n\n正确选项：books 是数据抽象、SEARCH 是过程抽象，都降低复杂度", source: "ai-mcq", verified: true },
  { id: "csp-scenario-050", deck: "csp-scenario", category: "AP CSP · 情境题", difficulty: 3, front: "学生的 Create task 程序通过了 3 组测试数据，但输入空列表时会崩溃；程序中还用了一段署名「CC BY-NC」的音乐，而他准备把作品发布到收费的学习平台。哪项最合适？\nA. 三个用例都通过就说明程序正确，空列表崩溃不必记录\nB. CC BY-NC 允许任何用途，只要保留原作者的署名即可\nC. 只要在报告中注明音乐名称，就不必考虑许可与测试\nD. 应补充空列表测试并记录，该收费用途不符合 NC 条款", back: "答案：D\n简析：一句话解析：A 把通过三个用例等同于程序正确并想隐瞒空列表崩溃，B 误以为 CC BY-NC 允许商业使用（发布到收费平台属于商业用途），C 以为注明音乐名称就能替代许可与测试记录；应补充空列表测试并如实记录，同时该收费用途不符合 NC 条款。\n\n正确选项：应补充空列表测试并记录，该收费用途不符合 NC 条款", source: "ai-mcq", verified: true },
];
